/// `(key, title, body values)`; empty body means the field is absent.
type DocSpec = (&'static str, &'static str, &'static [&'static str]);

const LEGACY_DOCS: [DocSpec; 8] = [
    (
        "d1",
        "rust systems search",
        &["rust is fast", "memory safety"],
    ),
    ("d2", "rust language guide", &["rust and cargo"]),
    ("d3", "python scripting", &[]),
    ("d4", "java virtual machine", &["java rust"]),
    ("d5", "rust basics", &["introductory rust"]),
    ("d6", "rust manual", &["advanced rust"]),
    ("d7", "search engines", &["search and rust"]),
    ("d8", "", &["empty title doc"]),
];

const APPENDED_DOCS: [DocSpec; 2] = [
    ("n1", "rust async runtime", &["tokio rust"]),
    ("n2", "generic rust traits", &["rust abstractions"]),
];

fn fixture_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/index/pr07_pre_norms_v1")
}

fn sha256(bytes: &[u8]) -> String {
    use std::fmt::Write as _;
    let digest = sha2::Sha256::digest(bytes);
    let mut out = String::with_capacity(64);
    for byte in digest.iter() {
        write!(out, "{byte:02x}").expect("string write");
    }
    out
}

fn copy_dir(src: &Path, dst: &Path) {
    std::fs::create_dir_all(dst).expect("mkdir");
    for entry in std::fs::read_dir(src).expect("read_dir") {
        let entry = entry.expect("entry");
        let to = dst.join(entry.file_name());
        if entry.file_type().expect("type").is_dir() {
            copy_dir(&entry.path(), &to);
        } else {
            std::fs::copy(entry.path(), &to).expect("copy");
        }
    }
}

/// Copy the committed fixture into a unique temporary root (`index/...`).
fn stage_fixture(tag: &str) -> TempDir {
    let temp = TempDir::new(tag);
    copy_dir(&fixture_root().join("index"), &temp.path().join("index"));
    temp
}

fn directory(path: &Path) -> Arc<dyn Directory> {
    Arc::new(FsDirectory::open(path).expect("fs directory"))
}

fn open_fixture(path: &Path) -> Index {
    Index::open_existing(directory(path), pr07_schema(), pr07_registry()).expect("open fixture")
}

fn open_fixture_result(path: &Path) -> Result<Index, IndexError> {
    Index::open_existing(directory(path), pr07_schema(), pr07_registry())
}

fn document(key: &str, title: &str, body: &[&str]) -> Document {
    let mut doc = Document::new(DocumentKey::new(key).expect("key"));
    doc.insert(
        "title",
        FieldValues::Single(FieldValue::Text(title.to_owned())),
    )
    .expect("title");
    if !body.is_empty() {
        let values = if body.len() == 1 {
            FieldValues::Single(FieldValue::Text(body[0].to_owned()))
        } else {
            FieldValues::Multi(
                body.iter()
                    .map(|value| FieldValue::Text((*value).to_owned()))
                    .collect(),
            )
        };
        doc.insert("body", values).expect("body");
    }
    doc.insert("n", FieldValues::Single(FieldValue::I64(0)))
        .expect("n");
    doc
}

fn term(field: &str, value: &str) -> Query {
    Query::Term {
        field: field.to_owned(),
        value: FieldValue::Text(value.to_owned()),
    }
}

fn search(snapshot: &ReaderSnapshot, query: &Query) -> SearchResponse {
    LexicalSearcher::new(
        snapshot,
        &pr07_schema(),
        &pr07_registry(),
        SearchLimits::default(),
    )
    .search(
        query,
        TopK::new(100).expect("topk"),
        &Budgets::new(),
        &NeverCancel,
    )
    .expect("search")
}

fn hits(response: &SearchResponse) -> Vec<(String, f64)> {
    response
        .hits
        .iter()
        .map(|hit| (hit.key.as_str().to_owned(), hit.score))
        .collect()
}

fn assert_hits_match(actual: &[(String, f64)], expected: &[(String, f64)]) {
    assert_eq!(
        actual.iter().map(|(k, _)| k.clone()).collect::<Vec<_>>(),
        expected.iter().map(|(k, _)| k.clone()).collect::<Vec<_>>(),
        "ordered keys differ"
    );
    for ((key, actual), (_, expected)) in actual.iter().zip(expected) {
        assert!(
            (actual - expected).abs() < 1e-10,
            "score mismatch for {key}: {actual} vs {expected}"
        );
    }
}

// ---------------------------------------------------------------------------
// Independent oracle
// ---------------------------------------------------------------------------

fn reference_bm25(tf: u64, df: u64, n: u64, dl: u64, avgdl: f64) -> f64 {
    if tf == 0 {
        return 0.0;
    }
    let (k1, b) = (1.2_f64, 0.75_f64);
    let idf = (1.0 + (n as f64 - df as f64 + 0.5) / (df as f64 + 0.5)).ln();
    let tf = tf as f64;
    let dl = dl as f64;
    idf * (tf * (k1 + 1.0)) / (tf + k1 * (1.0 - b + b * dl / avgdl))
}

fn title_len(key: &str) -> u64 {
    match key {
        "d1" | "d2" | "d4" | "n1" | "n2" => 3,
        "d3" | "d5" | "d6" | "d7" => 2,
        "d8" => 0,
        other => panic!("unknown key {other}"),
    }
}

fn title_rust_tf(key: &str) -> u64 {
    u64::from(matches!(key, "d1" | "d2" | "d5" | "d6" | "n1" | "n2"))
}

fn body_len(key: &str) -> u64 {
    match key {
        "d1" => 5,
        "d2" => 3,
        "d3" => 0,
        "d4" | "d5" | "d6" => 2,
        "d7" => 3,
        "d8" => 3,
        "n1" | "n2" => 2,
        other => panic!("unknown key {other}"),
    }
}

fn body_rust_tf(key: &str) -> u64 {
    u64::from(matches!(
        key,
        "d1" | "d2" | "d4" | "d5" | "d6" | "d7" | "n1" | "n2"
    ))
}

/// Expected ordered `(key, score)` for a single-field `rust` query over `corpus`.
fn expected_rust_scores(
    corpus: &[DocSpec],
    len: fn(&str) -> u64,
    tf: fn(&str) -> u64,
) -> Vec<(String, f64)> {
    let n = corpus.len() as u64;
    let total: u64 = corpus.iter().map(|(key, _, _)| len(key)).sum();
    let avgdl = total as f64 / n as f64;
    let df = corpus.iter().filter(|(key, _, _)| tf(key) > 0).count() as u64;
    let mut rows: Vec<(String, f64)> = corpus
        .iter()
        .filter(|(key, _, _)| tf(key) > 0)
        .map(|(key, _, _)| {
            (
                (*key).to_owned(),
                reference_bm25(tf(key), df, n, len(key), avgdl),
            )
        })
        .collect();
    rows.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    rows
}

/// Expected ordered `(key, score)` for `Or(title:rust, body:rust)`.
fn expected_rust_or_scores(corpus: &[DocSpec]) -> Vec<(String, f64)> {
    let title = expected_rust_scores(corpus, title_len, title_rust_tf);
    let body = expected_rust_scores(corpus, body_len, body_rust_tf);
    let mut sums: BTreeMap<String, f64> = BTreeMap::new();
    for (key, score) in title.into_iter().chain(body) {
        *sums.entry(key).or_insert(0.0) += score;
    }
    let mut rows: Vec<(String, f64)> = sums.into_iter().collect();
    rows.sort_by(|a, b| b.1.total_cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    rows
}

fn analyzed_len(registry: &AnalyzerRegistry, analyzer: &str, values: &[&str]) -> u64 {
    let definition = registry.get(analyzer).expect("analyzer");
    definition
        .collect_tokens(
            AnalyzerRole::Index,
            values,
            &AnalysisLimits::default(),
            &NeverCancel,
        )
        .expect("analyze")
        .len() as u64
}

fn analyzed_tf(registry: &AnalyzerRegistry, analyzer: &str, values: &[&str], term: &str) -> u64 {
    let definition = registry.get(analyzer).expect("analyzer");
    definition
        .collect_tokens(
            AnalyzerRole::Index,
            values,
            &AnalysisLimits::default(),
            &NeverCancel,
        )
        .expect("analyze")
        .iter()
        .filter(|token| token.term() == term)
        .count() as u64
}

/// CF-I07/T08 — the hand-tabulated oracle agrees with the pinned analyzers.
#[test]
fn cf_t08_oracle_tables_match_pinned_analyzers() {
    let registry = pr07_registry();
    for (key, title, body) in LEGACY_DOCS.iter().chain(APPENDED_DOCS.iter()) {
        assert_eq!(
            analyzed_len(&registry, "english", &[title]),
            title_len(key),
            "title length for {key}"
        );
        assert_eq!(
            analyzed_tf(&registry, "english", &[title], "rust"),
            title_rust_tf(key),
            "title rust tf for {key}"
        );
        assert_eq!(
            analyzed_len(&registry, "standard_folded", body),
            body_len(key),
            "body length for {key}"
        );
        assert_eq!(
            analyzed_tf(&registry, "standard_folded", body, "rust"),
            body_rust_tf(key),
            "body rust tf for {key}"
        );
    }
}

