#[test]
fn cf_t01_fixture_objects_are_pinned() {
    let root = fixture_root();
    for (rel, length, digest) in FIXTURE_OBJECTS {
        let bytes = std::fs::read(root.join(rel)).expect("fixture object");
        assert_eq!(bytes.len() as u64, length, "length for {rel}");
        assert_eq!(sha256(&bytes), digest, "sha256 for {rel}");
    }
    // Normal tests must not require the historical worktree; only these bytes.
    assert!(!root.join(".git").exists());
}

#[test]
fn cf_t02_current_opens_legacy_segments_without_norms() {
    let temp = stage_fixture("cf-t02");
    let index = open_fixture(temp.path());
    assert_eq!(index.generation(), Some(1), "historical generation");
    let snapshot = index.snapshot();
    assert_eq!(snapshot.segment_count(), 2, "two legacy segments");
    let expected: [(&str, &[&str]); 2] = [
        (
            "0508682861380e974057c33f1f702713f0d38643ebd55eee12edeeedb3b94b4e",
            &["d1", "d2", "d3", "d4"],
        ),
        (
            "da391e76a490450b371d3ea963dd06e4a58d269974d52d1460b26c0083faf558",
            &["d5", "d6", "d7", "d8"],
        ),
    ];
    for (segment, guard) in (0..snapshot.segment_count()).map(|segment| {
        (
            segment,
            snapshot
                .open_segment_reader(segment)
                .expect("segment reader"),
        )
    }) {
        assert!(
            guard.reader().field_norms().is_none(),
            "legacy segment {segment} must not carry norms"
        );
        assert!(
            !guard
                .reader()
                .required_features()
                .iter()
                .any(|(id, _)| *id == FEATURE_FIELD_NORMS),
            "legacy segment {segment} must not require norms"
        );
        // Immutable segment identity: content digest and committed keys per segment.
        let (digest, keys) = expected[segment];
        assert_eq!(sha256(snapshot.segments()[segment].bytes()), digest);
        let stored: Vec<String> = guard
            .reader()
            .stored()
            .expect("stored")
            .iter()
            .map(|record| record.key.as_str().to_owned())
            .collect();
        assert_eq!(
            stored,
            keys.iter().map(|key| (*key).to_owned()).collect::<Vec<_>>()
        );
    }
}

