#[test]
fn cf_t03_legacy_scored_term_search_matches_oracle() {
    let temp = stage_fixture("cf-t03");
    let index = open_fixture(temp.path());
    let snapshot = index.snapshot();

    let response = search(&snapshot, &term("title", "rust"));
    assert_eq!(response.generation, Some(1), "generation reported");
    assert_eq!(response.total_hits, 4, "four title matches");
    assert_hits_match(
        &hits(&response),
        &expected_rust_scores(&LEGACY_DOCS, title_len, title_rust_tf),
    );

    let response = search(&snapshot, &term("body", "rust"));
    assert_eq!(response.total_hits, 6);
    assert_hits_match(
        &hits(&response),
        &expected_rust_scores(&LEGACY_DOCS, body_len, body_rust_tf),
    );
}

#[test]
fn cf_t04_legacy_or_absent_field_and_match_all() {
    let temp = stage_fixture("cf-t04");
    let index = open_fixture(temp.path());
    let snapshot = index.snapshot();

    let response = search(
        &snapshot,
        &Query::Or(vec![term("title", "rust"), term("body", "rust")]),
    );
    assert_hits_match(&hits(&response), &expected_rust_or_scores(&LEGACY_DOCS));

    // A term that can only live in the absent `d3` body field matches nothing.
    let absent = search(&snapshot, &term("body", "python"));
    assert_eq!(absent.total_hits, 0);
    assert!(absent.hits.is_empty());

    let match_all = search(&snapshot, &Query::MatchAll);
    assert_eq!(
        match_all.total_hits, 8,
        "all live docs, including empty title"
    );
    assert!(match_all.hits.iter().all(|hit| hit.score == 0.0));
    let keys: Vec<String> = match_all
        .hits
        .iter()
        .map(|hit| hit.key.as_str().to_owned())
        .collect();
    assert_eq!(
        keys,
        vec!["d1", "d2", "d3", "d4", "d5", "d6", "d7", "d8"],
        "match-all tie order is key ascending"
    );
}

// ---------------------------------------------------------------------------
// CF-T05/T06/T07/T08 — mixed-format committed generation
// ---------------------------------------------------------------------------

/// Append the new-format batch, commit generation 2, and reopen the index.
fn append_and_reopen(temp: &Path) -> Index {
    let index = open_fixture(temp);
    let mut writer = index.writer().expect("writer");
    for (key, title, body) in APPENDED_DOCS {
        writer.insert(document(key, title, body)).expect("insert");
    }
    writer.flush().expect("flush");
    let outcome = writer.commit().expect("commit");
    assert_eq!(outcome.generation, 2, "second committed generation");
    assert_eq!(outcome.segments_added, 1, "one new segment");
    drop(writer);
    open_fixture(temp)
}

#[test]
fn cf_t05_mixed_generation_has_legacy_and_norms_segments() {
    let temp = stage_fixture("cf-t05");
    let index = append_and_reopen(temp.path());
    assert_eq!(index.generation(), Some(2));
    let snapshot = index.snapshot();
    assert_eq!(snapshot.segment_count(), 3, "two legacy plus one new");

    let mut legacy = 0;
    let mut norms = 0;
    for segment in 0..snapshot.segment_count() {
        let guard = snapshot
            .open_segment_reader(segment)
            .expect("segment reader");
        if guard.reader().field_norms().is_some() {
            norms += 1;
            assert!(
                guard
                    .reader()
                    .required_features()
                    .iter()
                    .any(|(id, version)| *id == FEATURE_FIELD_NORMS && *version == 1)
            );
        } else {
            legacy += 1;
        }
    }
    assert_eq!(legacy, 2, "two legacy segments retained");
    assert_eq!(norms, 1, "one new-format segment appended");
}

#[test]
fn cf_t06_mixed_scored_search_spans_both_formats() {
    let temp = stage_fixture("cf-t06");
    let index = append_and_reopen(temp.path());
    let snapshot = index.snapshot();
    let corpus: Vec<DocSpec> = LEGACY_DOCS
        .iter()
        .chain(APPENDED_DOCS.iter())
        .copied()
        .collect();

    let response = search(&snapshot, &term("title", "rust"));
    assert_eq!(response.total_hits, 6);
    assert_eq!(response.generation, Some(2));
    assert_hits_match(
        &hits(&response),
        &expected_rust_scores(&corpus, title_len, title_rust_tf),
    );

    let response = search(&snapshot, &term("body", "rust"));
    assert_eq!(response.total_hits, 8);
    assert_hits_match(
        &hits(&response),
        &expected_rust_scores(&corpus, body_len, body_rust_tf),
    );
}

#[test]
fn cf_t07_mixed_matches_all_new_full_corpus() {
    let mixed_temp = stage_fixture("cf-t07-mixed");
    let mixed = append_and_reopen(mixed_temp.path());
    let mixed_snapshot = mixed.snapshot();

    // All-new full corpus with equivalent three-segment grouping.
    let all_new_temp = TempDir::new("cf-t07-all-new");
    let directory: Arc<dyn Directory> = directory(all_new_temp.path());
    let created = Index::create(directory, pr07_schema(), pr07_registry()).expect("create all-new");
    let mut writer = created.writer().expect("writer");
    for batch in [&LEGACY_DOCS[0..4], &LEGACY_DOCS[4..8], &APPENDED_DOCS[..]] {
        for (key, title, body) in batch.iter() {
            writer.insert(document(key, title, body)).expect("insert");
        }
        writer.flush().expect("flush");
    }
    writer.commit().expect("commit");
    drop(writer);
    let all_new = open_fixture(all_new_temp.path());
    assert_eq!(all_new.generation(), Some(1));
    assert_eq!(all_new.snapshot().segment_count(), 3);
    let all_new_snapshot = all_new.snapshot();

    let queries = [
        term("title", "rust"),
        term("body", "rust"),
        Query::Or(vec![term("title", "rust"), term("body", "rust")]),
        Query::MatchAll,
    ];
    for query in &queries {
        let mixed_response = search(&mixed_snapshot, query);
        let all_new_response = search(&all_new_snapshot, query);
        assert_eq!(
            mixed_response.total_hits, all_new_response.total_hits,
            "total hits differ for {query:?}"
        );
        assert_hits_match(&hits(&mixed_response), &hits(&all_new_response));
    }
}

#[test]
fn cf_t08_mixed_cross_segment_oracle() {
    let temp = stage_fixture("cf-t08");
    let index = append_and_reopen(temp.path());
    let snapshot = index.snapshot();
    let corpus: Vec<DocSpec> = LEGACY_DOCS
        .iter()
        .chain(APPENDED_DOCS.iter())
        .copied()
        .collect();

    let response = search(
        &snapshot,
        &Query::Or(vec![term("title", "rust"), term("body", "rust")]),
    );
    assert_hits_match(&hits(&response), &expected_rust_or_scores(&corpus));

    // TopK smaller than total hits must not change the exact count or ordering.
    let top2 = LexicalSearcher::new(
        &snapshot,
        &pr07_schema(),
        &pr07_registry(),
        SearchLimits::default(),
    )
    .search(
        &term("title", "rust"),
        TopK::new(2).expect("topk"),
        &Budgets::new(),
        &NeverCancel,
    )
    .expect("search");
    assert_eq!(top2.total_hits, 6, "total hits is exact, not truncated");
    let expected = expected_rust_scores(&corpus, title_len, title_rust_tf);
    assert_hits_match(&hits(&top2), &expected[..2]);
}

