#[test]
fn cf_t09_fs_reopen_is_stable() {
    let temp = stage_fixture("cf-t09");
    // The immutable legacy objects (generation-1 manifest and both segments) must
    // not be rewritten by a generation-2 append; `CURRENT` is the mutable pointer.
    let immutable: [&str; 3] = [MANIFEST_REL, SEGMENT_1_REL, SEGMENT_2_REL];
    let snapshot_hashes = |path: &Path| -> Vec<String> {
        immutable
            .iter()
            .map(|rel| sha256(&std::fs::read(path.join(rel)).expect("read")))
            .collect()
    };
    let before = snapshot_hashes(temp.path());

    let first = {
        let index = append_and_reopen(temp.path());
        let snapshot = index.snapshot();
        hits(&search(&snapshot, &term("title", "rust")))
    };
    let second = {
        let index = open_fixture(temp.path());
        assert_eq!(index.generation(), Some(2));
        let snapshot = index.snapshot();
        hits(&search(&snapshot, &term("title", "rust")))
    };
    assert_hits_match(&first, &second);

    assert_eq!(
        before,
        snapshot_hashes(temp.path()),
        "immutable legacy objects must not be rewritten"
    );
}

/// CF-T14 — a read-only search never rewrites any fixture object, including
/// `CURRENT`.
#[test]
fn cf_t14_read_only_search_preserves_all_fixture_bytes() {
    let temp = stage_fixture("cf-t14");
    let before: Vec<String> = FIXTURE_OBJECTS
        .iter()
        .map(|(rel, _, _)| sha256(&std::fs::read(temp.path().join(rel)).expect("read")))
        .collect();

    let index = open_fixture(temp.path());
    let snapshot = index.snapshot();
    let _ = search(&snapshot, &term("title", "rust"));
    let _ = search(&snapshot, &term("body", "rust"));
    let _ = search(&snapshot, &Query::MatchAll);

    let after: Vec<String> = FIXTURE_OBJECTS
        .iter()
        .map(|(rel, _, _)| sha256(&std::fs::read(temp.path().join(rel)).expect("read")))
        .collect();
    assert_eq!(
        before, after,
        "read-only search must not rewrite fixture bytes"
    );
}

#[test]
fn cf_t10_pit_snapshot_is_immutable_across_mixed_commit() {
    let temp = stage_fixture("cf-t10");
    let index = open_fixture(temp.path());
    let pinned = index.pin().expect("pin legacy generation");
    let pinned_snapshot = Arc::clone(pinned.snapshot());
    assert_eq!(pinned_snapshot.segment_count(), 2);

    // Append a new-format generation while the PIT is held.
    let mut writer = index.writer().expect("writer");
    for (key, title, body) in APPENDED_DOCS {
        writer.insert(document(key, title, body)).expect("insert");
    }
    writer.flush().expect("flush");
    writer.commit().expect("commit");
    drop(writer);

    // The pinned snapshot still sees only the legacy generation.
    let pinned_response = search(&pinned_snapshot, &term("title", "rust"));
    assert_eq!(
        pinned_response.total_hits, 4,
        "old PIT sees only legacy docs"
    );
    assert_hits_match(
        &hits(&pinned_response),
        &expected_rust_scores(&LEGACY_DOCS, title_len, title_rust_tf),
    );

    // A fresh open observes the mixed generation.
    let reopened = open_fixture(temp.path());
    assert_eq!(reopened.generation(), Some(2));
    let new_response = search(&reopened.snapshot(), &term("title", "rust"));
    assert_eq!(
        new_response.total_hits, 6,
        "new generation includes appended docs"
    );
}

