#[test]
fn cf_t11_missing_current_and_referenced_objects_fail_closed() {
    // Missing CURRENT.
    let no_current = stage_fixture("cf-t11-current");
    std::fs::remove_file(no_current.path().join(CURRENT_REL)).expect("remove CURRENT");
    assert!(matches!(
        open_fixture_result(no_current.path()),
        Err(IndexError::NotInitialized)
    ));

    // Missing referenced segment.
    let no_segment = stage_fixture("cf-t11-segment");
    std::fs::remove_file(no_segment.path().join(SEGMENT_2_REL)).expect("remove segment");
    assert!(matches!(
        open_fixture_result(no_segment.path()),
        Err(IndexError::Storage(_))
    ));

    // Missing manifest.
    let no_manifest = stage_fixture("cf-t11-manifest");
    std::fs::remove_file(no_manifest.path().join(MANIFEST_REL)).expect("remove manifest");
    assert!(matches!(
        open_fixture_result(no_manifest.path()),
        Err(IndexError::Storage(_))
    ));
}

#[test]
fn cf_t12_tampered_referenced_segment_fails_closed() {
    let temp = stage_fixture("cf-t12");
    let segment = temp.path().join(SEGMENT_1_REL);
    let mut bytes = std::fs::read(&segment).expect("read segment");
    let last = bytes.len() - 1;
    bytes[last] ^= 0xFF;
    std::fs::write(&segment, &bytes).expect("write tampered segment");
    assert!(matches!(
        open_fixture_result(temp.path()),
        Err(IndexError::CorruptCommittedState { .. })
    ));
}
